// Generates core/search/cities-data.ts from the Go package's cities.tsv.gz (GeoNames, CC BY 4.0), so the on-device core and the Go core read one table.
// Run from exact-ui: bun scripts/gen-cities.ts
import { readFileSync, writeFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';

const source = new URL('../../internal/core/domain/geo/cities.tsv.gz', import.meta.url);
const out = new URL('../core/search/cities-data.ts', import.meta.url);
const tsv = gunzipSync(readFileSync(source)).toString('utf8');
const header =
  '// Generated by scripts/gen-cities.ts from internal/core/domain/geo/cities.tsv.gz (GeoNames, CC BY 4.0). Do not edit by hand.\n' +
  '// One line per name: folded name, tab, comma-separated country codes (most populous first), tab, display name.\n';
writeFileSync(out, `${header}export const citiesTsv: string = ${JSON.stringify(tsv)};\n`);
console.log(`${tsv.split('\n').length - 1} lines, ${tsv.length} characters`);
